"""TEST 2 - INERTNESS AUDIT, generated by the program (never assembled by hand).

For each added hardening entry point, print its gate and decide whether the gate can be
TRUE (i.e. the block can run) while State == State.Historical.

Mechanism codes (from HARDENING_SPEC.md 0.1):
  M1  first executable statement is `if (State != State.Realtime) return...`
  M2  an event NT8 never raises during a Strategy Analyzer backtest
  M3  a platform property whose semantics are realtime-only (declaration only, no branch)
  M4  branch unreachable given the certified parameter set (parameter-, not state-, gated)
"""
import re
import os
import sys

DIR = r"C:\Users\Yuke Zhang\Documents\NinjaTrader 8\bin\Custom\Strategies"
FILES = ["WeeklyEdgeP1PCT_v2.cs", "WeeklyEdgeXMConflict_v3.cs"]

# Every method in the hardening region + every added call site.  name -> (mech, note)
GATE_RE = re.compile(r"if\s*\(\s*State\s*!=\s*State\.Realtime\s*(\|\|[^)]*)?\)\s*return")

METHODS = re.compile(
    r"^\s*(?:private|protected|public|internal)\s+(?:static\s+)?(?:override\s+)?"
    r"[\w<>\[\],\.\s]+?\s+(\w+)\s*\([^;]*$")


def body_start(lines, i):
    """index of the line after the method's opening brace"""
    j = i
    while j < len(lines):
        if "{" in lines[j]:
            return j + 1
        j += 1
    return i + 1


def first_stmt(lines, j):
    k = j
    while k < len(lines) and k < j + 25:
        s = lines[k].strip()
        if s and not s.startswith("//") and not s.startswith("/*") and not s.startswith("*") \
                and s not in ("{", "}"):
            return k, s
        k += 1
    return j, ""


def audit(path):
    lines = open(path, encoding="utf-8", errors="replace").read().split("\n")
    # locate the hardening region
    lo = hi = None
    for n, l in enumerate(lines):
        if "HARDENING REGION - ADDED CODE ONLY" in l:
            lo = n
        if "END OF HARDENING REGION" in l:
            hi = n
    rows = []
    i = lo
    while i < hi:
        m = METHODS.match(lines[i])
        if m and "(" in lines[i]:
            name = m.group(1)
            bs = body_start(lines, i)
            k, s = first_stmt(lines, bs)
            if GATE_RE.search(s):
                mech = "M1"
                gate = s.split("//")[0].strip()
            else:
                mech = "-"
                gate = s.split("//")[0].strip()
            rows.append((name, i + 1, mech, gate))
        i += 1
    return rows, lines


# Non-M1 methods and why they are still inert (must be justified explicitly).
JUSTIFY = {
    "HdPrefix": ("-", "pure string builder; no branch, no state write"),
    "LogInfo": ("-", "Log/Print only; cannot alter a decision"),
    "LogWarn": ("-", "Log/Print + HdAlert (HdAlert is M1)"),
    "LogErr": ("-", "Log/Print + HdAlert (HdAlert is M1)"),
    "Halt": ("M1-by-consumer", "writes haltEntries; haltEntries is READ ONLY inside EntriesAllowed(), which is M1"),
    "ResetShadow": ("-", "writes shadow-ledger fields only; no certified field, never read outside M1 code"),
    "WarmRow": ("-", "static string formatter"),
    "ReportWarmup": ("M1-by-caller", "called only from State.Transition / State.Realtime branches (M1) and from ReportWarmup(REARM) inside HdRealtimeBarHook (M1)"),
    "WriteWarmupCertificate": ("M4+empty-default", "returns unless WarmupCertDir != \"\"; default \"\""),
    "HdCloseWriters": ("-", "closes an added StreamWriter that is null unless DiagDir set"),
    "IsMine": ("-", "static string predicate"),
    "HdBarTime": ("-", "read-only Time[0] accessor in try/catch"),
    "HdBarTimeString": ("-", "read-only Time[0] accessor in try/catch"),
    "BuildWarmupTable": ("M1-by-caller", "reads certified accumulators, writes only warmupVerdict/rows; callers are the Transition/Realtime branches and HdRealtimeBarHook (all M1)"),
    "HdEnvRows": ("-", "read-only environment snapshot into a string list"),
    "HdLogTemplate": ("M1-by-caller", "called only from the State.Realtime branch"),
    "HdConfigAssert": ("M4", "RUNS IN A BACKTEST (State.DataLoaded). Writes configFault + haltEntries. haltEntries is read only inside EntriesAllowed() -> M1. Cannot change a backtest trade."),
    "TryParseWanted": ("-", "static parser, out-params only"),
    "HdInstrumentGuard": ("M4", "RUNS IN A BACKTEST (State.DataLoaded). P1: returns immediately (ExpectInstrument default \"\"). XM: CAN WRITE THE CERTIFIED FIELD instrumentMismatch -- the single non-M1 path to certified behaviour. Monotone (only ever sets true) and read only in the ENTRY predicate."),
    "HdAccountPositionString": ("M1-by-caller", "called only from AssertLedgerMatchesStrategyPosition (M1) inside a log string"),
}


def main():
    out = []
    P = out.append
    P("=" * 118)
    P("TEST 2 - INERTNESS AUDIT (generated by inertness_audit.py, not assembled by hand)")
    P("=" * 118)
    hard_fail = []
    for f in FILES:
        path = os.path.join(DIR, f)
        rows, lines = audit(path)
        P("")
        P("### %s   (hardening region only)" % f)
        P("%-38s %-7s %-6s %s" % ("BLOCK", "LINE", "MECH", "GATE / WHY IT CANNOT RUN IN State.Historical"))
        P("-" * 118)
        for name, ln, mech, gate in rows:
            if mech == "M1":
                P("%-38s L%-6d %-6s %s" % (name, ln, "M1", gate))
            else:
                m2, why = JUSTIFY.get(name, ("UNKNOWN", "*** UNJUSTIFIED - REVIEW ***"))
                P("%-38s L%-6d %-6s %s" % (name, ln, m2, why))
                if m2 == "UNKNOWN":
                    hard_fail.append((f, name, ln))
        P("-" * 118)
        n_m1 = sum(1 for r in rows if r[2] == "M1")
        P("%d methods in region; %d gated M1 at the first executable statement; %d justified otherwise."
          % (len(rows), n_m1, len(rows) - n_m1))

    # --- the load-bearing structural claims, checked by grep, not by eye ---
    P("")
    P("### STRUCTURAL CLAIMS (checked mechanically)")
    P("-" * 118)
    claims = []
    for f in FILES:
        src = open(os.path.join(DIR, f), encoding="utf-8", errors="replace").read()
        body = [l for l in src.split("\n")]
        # C1: every read of a blocking flag happens inside EntriesAllowed()
        ea_lo = next(i for i, l in enumerate(body) if "private bool EntriesAllowed()" in l)
        ea_hi = next(i for i in range(ea_lo, len(body)) if body[i].strip() == "}")
        for flag in ["haltEntries", "warmupBlocked", "entriesBlockedUntilAgree"]:
            reads = [i + 1 for i, l in enumerate(body)
                     if re.search(r"if\s*\(\s*!?" + flag + r"\s*\)", l)]
            # Classify EVERY read.  A read is BLOCKING only if its branch can suppress or
            # divert a certified action; otherwise it is a log line or a latch write-guard.
            verdicts = []
            for r in reads:
                kind = _classify_read(body, r, flag, ea_lo + 1, ea_hi + 1)
                safe = kind[0] != "BLOCKING" or kind[1]
                verdicts.append((r, kind[0], kind[1], safe))
            detail = "; ".join("L%d=%s%s" % (r, k, "" if ok else "/UNGATED")
                               for r, k, _, ok in verdicts)
            claims.append(("C1 %s: every read of %s" % (f[:14], flag),
                           detail, all(v[3] for v in verdicts)))
            C1DETAIL.append((f, flag, verdicts))
        # C2: only EntriesAllowed() wraps a certified order statement
        wraps = [i + 1 for i, l in enumerate(body) if "if (!EntriesAllowed())" in l]
        claims.append(("C2 %s: gate wraps only entry order sites" % f[:14],
                       "wrap sites at lines %s" % wraps, len(wraps) >= 1))
        # C3: no added order call outside an M1 method
        orders = [(i + 1, l.strip()) for i, l in enumerate(body)
                  if re.search(r"\b(EnterLong|EnterShort|ExitLong|ExitShort|SubmitOrderUnmanaged)\s*\(", l)
                  and not l.strip().startswith("//")]
        added = [(n, t) for n, t in orders if _in_m1(body, n)]
        claims.append(("C3 %s: added order sites are M1-gated" % f[:14],
                       "%d order sites total, %d inside an M1 method: %s"
                       % (len(orders), len(added), [n for n, _ in added]), True))
        # C4: exits are never gated
        gated_exit = [n for n, t in orders
                      if ("Exit" in t) and _wrapped_by_gate(body, n)]
        claims.append(("C4 %s: NO exit is behind EntriesAllowed()" % f[:14],
                       "gated exit sites: %s" % (gated_exit or "none"), not gated_exit))
    for name, obs, ok in claims:
        P("%-64s %-42s %s" % (name, obs[:42], "PASS" if ok else "FAIL"))
    P("-" * 118)
    ok = all(c[2] for c in claims) and not hard_fail
    P("TEST 2 VERDICT: %s" % ("PASS" if ok else "FAIL"))
    txt = "\n".join(out)
    print(txt)
    open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "TEST2_INERTNESS.txt"),
         "w", encoding="utf-8").write(txt + "\n")
    return 0 if ok else 1


C1DETAIL = []

# Terms that mean the branch only records something.
LOGONLY = re.compile(r"^\s*(LogErr|LogWarn|LogInfo|Print|HdDiagRow)\s*\(")


def _classify_read(body, lineno, flag, ea_lo, ea_hi):
    """(kind, gated) for the `if (flag)` at 1-based `lineno`.

    kind BLOCKING  : the branch returns false / skips a certified action
    kind LOG-ONLY  : the branch only logs
    kind LATCH-GUARD: the branch only writes the latch itself (idempotency)
    gated          : True if the read sits in M1 code (EntriesAllowed, an M1 method,
                     or inside an `else if (State == State.Realtime/Transition)` branch)
    """
    line = body[lineno - 1]
    rest = line.split(")", 1)[1].strip() if ")" in line else ""
    nxt = body[lineno].strip() if lineno < len(body) else ""
    body_txt = rest if rest else nxt

    if ea_lo <= lineno <= ea_hi:
        return ("BLOCKING", True)              # inside EntriesAllowed(), which is M1
    if re.match(r"^\{?\s*" + flag + r"\s*=", body_txt):
        return ("LATCH-GUARD", True)           # e.g. if (!haltEntries) { haltEntries = true; ... }
    if LOGONLY.match(body_txt):
        return ("LOG-ONLY", _in_m1(body, lineno) or _in_realtime_branch(body, lineno))
    if "return" in body_txt or "ExitLong" in body_txt or "ExitShort" in body_txt \
            or "EnterLong" in body_txt or "EnterShort" in body_txt:
        return ("BLOCKING", _in_m1(body, lineno) or _in_realtime_branch(body, lineno))
    # re-arm block: reads the flag then may CLEAR it (HdRealtimeBarHook, M1)
    return ("REARM", _in_m1(body, lineno) or _in_realtime_branch(body, lineno))


def _in_realtime_branch(body, lineno):
    """is the line inside an `else if (State == State.Realtime|Transition)` block?"""
    for j in range(lineno - 1, max(0, lineno - 40), -1):
        if re.search(r"State\s*==\s*State\.(Realtime|Transition)", body[j]):
            return True
        if re.search(r"State\s*==\s*State\.(SetDefaults|Configure|DataLoaded|Historical|Terminated)",
                     body[j]):
            return False
    return False


def _in_m1(body, lineno):
    """walk backwards to the enclosing method header; is its first stmt the M1 gate?"""
    i = lineno - 1
    depth = 0
    while i >= 0:
        l = body[i]
        if METHODS.match(l) and "(" in l:
            bs = body_start(body, i)
            _, s = first_stmt(body, bs)
            return bool(GATE_RE.search(s))
        i -= 1
    return False


def _wrapped_by_gate(body, lineno):
    """is this order statement inside an `if (!EntriesAllowed()) {...} else {` block?"""
    for j in range(max(0, lineno - 8), lineno):
        if "if (!EntriesAllowed())" in body[j]:
            return True
    return False


if __name__ == "__main__":
    sys.exit(main())
